319	/**
320	 * sanitizeDate: If date is >60 days in the future and day ≤ 12,
321	 * try swapping DD↔MM to fix BR↔US date mismatches.
322	 */
323	function sanitizeDate(dateStr: string | null | undefined): string | null {
324	    if (!dateStr) return null;
325	    const match = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
326	    if (!match) return dateStr;
327	
328	    const [, yearStr, monthStr, dayStr] = match;
329	    const year = parseInt(yearStr);
330	    const month = parseInt(monthStr);
331	    const day = parseInt(dayStr);
332	
333	    const parsed = new Date(year, month - 1, day);
334	    const today = new Date();
335	    today.setHours(0, 0, 0, 0);
336	
337	    const diffMs = parsed.getTime() - today.getTime();
338	    const diffDays = diffMs / (1000 * 60 * 60 * 24);
339	
340	    if (diffDays > 60 && day <= 12) {
341	        const swapped = new Date(year, day - 1, month);
342	        const swappedDiff =
343	            (swapped.getTime() - today.getTime()) / (1000 * 60 * 60 * 24);
344	        if (swappedDiff <= 60) {
345	            return `${yearStr}-${dayStr}-${monthStr}`;
346	        }
347	    }
348	    return dateStr;
349	}
