351	/**
352	 * normalizeItems: Merges duplicate products by name (case-insensitive).
353	 * Accumulates quantities and subtotals. Calculates unit price if missing.
354	 */
355	function normalizeItems(items: any[]): any[] {
356	    const map: Record<
357	        string,
358	        {
359	            nome_produto: string;
360	            quantidade: number;
361	            subtotal: number | null;
362	            valor_unitario: number | null;
363	            categoria: string | null;
364	        }
365	    > = {};
366	    for (const it of items || []) {
367	        const nome = String(it?.nome_produto || '').trim();
368	        if (!nome) continue;
369	        const key = nome.toLowerCase();
370	        const qtd =
371	            typeof it?.quantidade === 'string'
372	                ? parseFloat(it.quantidade)
373	                : (it?.quantidade ?? 0);
374	        const sub =
375	            typeof it?.subtotal === 'string'
376	                ? parseFloat(it.subtotal)
377	                : (it?.subtotal ?? null);
378	        const unit =
379	            typeof it?.valor_unitario === 'string'
380	                ? parseFloat(it.valor_unitario)
381	                : (it?.valor_unitario ?? null);
382	        const cat = (it?.categoria ?? null) as string | null;
383	        if (!map[key]) {
384	            map[key] = {
385	                nome_produto: nome,
386	                quantidade: 0,
387	                subtotal: null,
388	                valor_unitario: unit,
389	                categoria: cat,
390	            };
391	        }
392	        map[key].quantidade += qtd || 0;
393	        if (sub != null) {
394	            map[key].subtotal = (map[key].subtotal ?? 0) + sub;
395	        }
396	        if (map[key].valor_unitario == null && unit != null) {
397	            map[key].valor_unitario = unit;
398	        }
399	        if (map[key].categoria == null && cat != null) {
400	            map[key].categoria = cat;
401	        }
402	    }
403	    const result: any[] = [];
404	    for (const k in map) {
405	        const v = map[k];
406	        let unit = v.valor_unitario;
407	        if (
408	            (unit == null || isNaN(unit)) &&
409	            v.subtotal != null &&
410	            v.quantidade > 0
411	        ) {
412	            unit = Number((v.subtotal / v.quantidade).toFixed(4));
413	        }
414	        result.push({
415	            nome_produto: v.nome_produto,
416	            quantidade: Number(Number(v.quantidade || 0).toFixed(3)),
417	            valor_unitario: unit ?? null,
418	            subtotal:
419	                v.subtotal != null ? Number(Number(v.subtotal).toFixed(2)) : null,
420	            categoria: v.categoria,
421	        });
422	    }
423	    return result;
424	}
